// illustrative client (not in the repo)
async function call(url: string, tries = 3): Promise<Response> {
  const r = await fetch(url);
  if ((r.status === 429 || r.status === 503) && tries > 0) {
    const s = Number(r.headers.get("retry-after") ?? "1");
    await new Promise((ok) => setTimeout(ok, s * 1000 + Math.random() * 500)); // + jitter
    return call(url, tries - 1);
  }
  return r;
}

